export default function Animation({ progress }) {
  const visualSpec = {
    subject: "Gradient Descent Overview",
    view: "cost-function coordinate plane",
    recognitionCues: [
      "cost function curve",
      "tangent gradient",
      "iterative steps to minimum"
    ],
    requiredParts: [
      "J(m,b) curve",
      "gradient tangent",
      "successive parameter points",
      "minimum"
    ],
    relationships: [
      "gradient points toward lower cost",
      "updates move along the curve toward the minimum"
    ],
    morphology: "smooth convex optimization curve with traced iterations",
    forbiddenShortcuts: [
      "generic icon",
      "unlabeled blob",
      "decorative geometry",
      "physical hill or slope"
    ]
  };

  const boardPlan = {
    composition: "central coordinate plane with a traced optimization path",
    readingPath: "title, cost curve, tangent gradient, iterative points, minimum takeaway",
    reservedRegions: [
      { name: "title", x: 54, y: 30, w: 260, h: 46 },
      { name: "costLabel", x: 72, y: 175, w: 125, h: 32 },
      { name: "gradientLabel", x: 650, y: 166, w: 230, h: 32 },
      { name: "stepsLabel", x: 88, y: 455, w: 210, h: 32 },
      { name: "minimumLabel", x: 565, y: 456, w: 175, h: 32 },
      { name: "takeaway", x: 730, y: 455, w: 176, h: 32 },
      { name: "plot", x: 210, y: 150, w: 610, h: 292 },
      { name: "axisX", x: 790, y: 420, w: 42, h: 30 },
      { name: "axisY", x: 185, y: 145, w: 34, h: 30 }
    ]
  };

  const p = smooth(clamp01(progress));
  const cx = lerp(315, 525, p);
  const curveY = x => 205 + 0.0041 * Math.pow(x - 525, 2);
  const cy = curveY(cx);
  const tangentSlope = 0.0082 * (cx - 525);
  const tangentX1 = cx - 82;
  const tangentX2 = cx + 82;
  const tangentY1 = cy - tangentSlope * 82;
  const tangentY2 = cy + tangentSlope * 82;
  const pathProgress = phase(progress, 0.18, 0.74);
  const arrowX = lerp(315, 505, pathProgress);
  const arrowY = curveY(arrowX);

  return (
    <svg viewBox="0 0 1000 560" width="100%" height="100%">
      <rect x="0" y="0" width="1000" height="560" fill="#fbfbf8" />
      <rect x="54" y="30" width="892" height="500" rx="4"
        fill="none" stroke="#d1d5db" strokeWidth="2" />

      <text x="64" y="70" fontSize="34" fontWeight="700" fill="#1f2937"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={1} data-teach-kind="write" data-teach-weight={1}
        data-teach-sentence={0}>Gradient descent</text>

      <g data-teach-order={2} data-teach-kind="diagram" data-teach-weight={1.2}
        data-teach-sentence={0}>
        <line x1="220" y1="420" x2="820" y2="420" stroke="#1f2937" strokeWidth="3" />
        <line x1="220" y1="420" x2="220" y2="160" stroke="#1f2937" strokeWidth="3" />
        <polygon points="820,420 806,413 806,427" fill="#1f2937" />
        <polygon points="220,160 213,174 227,174" fill="#1f2937" />
        <line x1="340" y1="414" x2="340" y2="426" stroke="#6b7280" strokeWidth="2" />
        <line x1="525" y1="414" x2="525" y2="426" stroke="#6b7280" strokeWidth="2" />
        <line x1="700" y1="414" x2="700" y2="426" stroke="#6b7280" strokeWidth="2" />
      </g>

      <text x="82" y="198" fontSize="22" fill="#1f2937"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={3} data-teach-kind="label" data-teach-weight={0.9}
        data-teach-sentence={0}>Cost J(m,b)</text>

      <g data-teach-order={4} data-teach-kind="diagram" data-teach-weight={1.5}
        data-teach-sentence={0}>
        <path d="M 255 245 C 330 330, 390 392, 525 405 C 660 392, 720 330, 795 245"
          fill="none" stroke="#3b82f6" strokeWidth="6" strokeLinecap="round" />
      </g>

      <g data-teach-order={5} data-teach-kind="arrow" data-teach-weight={1.3}
        data-teach-sentence={1}>
        <path d={`M ${tangentX1} ${tangentY1} L ${tangentX2} ${tangentY2}`}
          fill="none" stroke="#be185d" strokeWidth="4" strokeDasharray="10 7" />
        <polygon
          points={`${tangentX2},${tangentY2} ${tangentX2 - 15},${tangentY2 - 3} ${tangentX2 - 8},${tangentY2 + 11}`}
          fill="#be185d"
          transform={`rotate(${Math.atan2(tangentY2 - tangentY1, tangentX2 - tangentX1) * 180 / Math.PI} ${tangentX2} ${tangentY2})`}
        />
      </g>

      <text x="650" y="190" fontSize="22" fill="#be185d"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={6} data-teach-kind="label" data-teach-weight={0.9}
        data-teach-sentence={2}>gradient direction</text>

      <g data-teach-order={7} data-teach-kind="diagram" data-teach-weight={1.4}
        data-teach-sentence={2}>
        <circle cx="315" cy={curveY(315)} r="10" fill="#d97706" stroke="#1f2937" strokeWidth="3" />
        <circle cx="405" cy={curveY(405)} r="9" fill="#14b8a6" stroke="#1f2937" strokeWidth="3" />
        <circle cx="470" cy={curveY(470)} r="9" fill="#65a30d" stroke="#1f2937" strokeWidth="3" />
        <circle cx={cx} cy={cy} r="13" fill="#d97706" stroke="#1f2937" strokeWidth="4" />
        <circle cx="525" cy="405" r="12" fill="#ffffff" stroke="#65a30d" strokeWidth="5" />
      </g>

      <g data-teach-order={8} data-teach-kind="arrow" data-teach-weight={1.1}
        data-teach-sentence={3}>
        <path d={`M 315 ${curveY(315) - 24} C 360 ${curveY(360) - 31}, 430 ${curveY(430) - 30}, ${arrowX} ${arrowY - 24}`}
          fill="none" stroke="#d97706" strokeWidth="4" strokeLinecap="round" />
        <polygon points={`${arrowX},${arrowY - 24} ${arrowX - 14},${arrowY - 32} ${arrowX - 11},${arrowY - 17}`}
          fill="#d97706" />
      </g>

      <text x="88" y="480" fontSize="22" fill="#d97706"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={9} data-teach-kind="annotate" data-teach-weight={0.9}
        data-teach-sentence={5}>step 1 → 2 → 3</text>

      <text x="565" y="480" fontSize="22" fill="#65a30d"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={10} data-teach-kind="label" data-teach-weight={0.9}
        data-teach-sentence={3}>minimum cost</text>

      <text x="730" y="480" fontSize="20" fill="#1f2937"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={11} data-teach-kind="reveal" data-teach-weight={1}
        data-teach-sentence={6}>iterative, not one step</text>

      <text x="790" y="448" fontSize="18" fill="#1f2937"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={12} data-teach-kind="label" data-teach-weight={0.7}
        data-teach-sentence={4}>parameters</text>

      <text x="190" y="154" fontSize="18" fill="#1f2937"
        fontFamily="Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif"
        data-teach-order={13} data-teach-kind="label" data-teach-weight={0.7}
        data-teach-sentence={1}>J</text>
    </svg>
  );
}
